            "flexDirection": "column",
            "alignItems": "center",
            "paddingTop": "var(--space-20)",
            "paddingBottom": "var(--space-20)"
          },
          "parent": "page",
          "children": [
            "shell"
          ]
        },
        {
          "id": "shell",
          "type": "Group",
          "label": "Shell",
          "parameters": {
            "width": {
              "value": 100,
              "unit": "%"
            },
            "maxWidth": {
              "value": 1200,
              "unit": "px"
            },
            "flexDirection": "column",
            "paddingLeft": "var(--space-6)",
            "paddingRight": "var(--space-6)"
          },
          "parent": "band",
          "children": [
            "grid"
          ]
        },
        {
          "id": "grid",
          "type": "net.noodl.visual.columns",
          "label": "Card grid",
          "parameters": {
            "sizing": "autoFit",
            "minWidth": {
              "value": 280,
              "unit": "px"
            },
            "marginX": {
              "value": 12,
              "unit": "px"
            }
          },
          "parent": "shell",
          "children": [
            "repeater"
          ]
        },
        {
          "id": "repeater",
          "type": "For Each",
          "label": "One card per record",
